@app.route("/nmt/diagnostic", methods=["GET", "POST"])
def nmt_diagnostic():
    """Коротка навчальна діагностика за трьома обов’язковими напрямами НМТ."""
    grade = active_grade()
    if grade != 11:
        abort(404)
    groups = [
        ("Українська мова", "ukr-mova", [2, 5, 8, 11]),
        ("Математика", "algebra", [3, 7, 10, 14]),
        ("Історія України", "history-ukraine", [1, 4, 7, 10]),
    ]
    questions = []
    for label, slug, lesson_ids in groups:
        subject = get_subject(slug, 11)
        if not subject:
            continue
        for lesson_id in lesson_ids:
            if lesson_id <= len(subject["lessons"]):
                lesson = subject["lessons"][lesson_id - 1]
                questions.append({"group": label, "slug": slug, "lesson_id": lesson_id,
                                  "title": lesson["title"], "question": lesson["question"],
                                  "options": lesson["options"], "answer": lesson["answer"]})
    scores, recommendations = {}, []
    if request.method == "POST":
        for i, q in enumerate(questions):
            selected = request.form.get(f"answer_{i}", "")
            scores[q["group"]] = scores.get(q["group"], 0) + (selected == str(q["answer"]))
            if selected != str(q["answer"]):
                recommendations.append(q)
    return show_page(
        "Діагностика до НМТ",
        """
        <section class="nmt-diagnostic"><nav class="crumb"><a href="{{ url_for('index', grade=11) }}">11 клас</a>　/　Діагностика</nav>
          <p class="eyebrow">ПЕРШИЙ КРОК ДО ПЛАНУ ПІДГОТОВКИ</p><h1>Коротка діагностика до НМТ</h1>
          <p class="intro">12 навчальних запитань: по чотири з української мови, математики й історії України. Це швидкий орієнтир для повторення, а не повний варіант НМТ. Відповіді не зберігаються.</p>
          {% if scores %}<section class="nmt-results" aria-live="polite"><h2>Твій результат</h2><div class="career-results-grid">{% for name, score in scores.items() %}<article><strong>{{ score }}/4</strong><span>{{ name }}</span></article>{% endfor %}</div>
            <h3>Що повторити далі</h3>{% if recommendations %}<ul>{% for q in recommendations %}<li><strong>{{ q.group }}:</strong> {{ q.title }} — <a href="{{ url_for('lesson_page', subject_slug=q.slug, lesson_id=q.lesson_id, grade=11) }}">відкрити пояснення</a></li>{% endfor %}</ul>{% else %}<p>Чудово — усі відповіді правильні. Продовжуй тренуватися на темах 11 класу.</p>{% endif %}</section>{% endif %}
          <form method="post" class="nmt-diagnostic-form">{% for q in questions %}{% set question_index = loop.index0 %}<fieldset class="lesson-panel"><legend><span class="pill">{{ q.group }}</span> {{ loop.index }}. {{ q.question }}</legend><p class="muted">Тема: {{ q.title }}</p>{% for option in q.options %}<label class="nmt-answer"><input type="radio" name="answer_{{ question_index }}" value="{{ loop.index0 }}" required> {{ option }}</label>{% endfor %}</fieldset>{% endfor %}<button class="button" type="submit">Перевірити відповіді</button></form>
        </section>
        """,
        grade=11, questions=questions, scores=scores, recommendations=recommendations,
        robots_noindex=True,
    )


NMT_ELECTIVE_COUNTS = {
    "ukr-lit": 30, "english": 32, "biology": 30,
    "geography": 30, "physics": 22, "chemistry": 24,
}


def nmt_question_bank(slugs, count, rng, subject_names=None):
    """Build a varied local practice bank from course checks, without storing answers."""
    subject_names = subject_names or {}
    pool = []
    for slug in slugs:
        subject = get_subject(slug, 11)
        if not subject:
            continue
        for lesson_id, lesson in enumerate(subject["lessons"], 1):
            for question in lesson.get("control_work", []):
                original_options = question.get("options", [])
                unique_options = list(dict.fromkeys(original_options))
                if len(unique_options) < 2:
                    continue
                correct_text = original_options[question["answer"]]
                pool.append({
                    "slug": slug, "lesson_id": lesson_id,
                    "subject": subject_names.get(slug, subject["name"]),
                    "title": lesson["title"], "question": question["question"],
                    "options": unique_options, "answer": unique_options.index(correct_text),
                    "explain": lesson.get("explain", ""),
                })
    rng.shuffle(pool)
    if len(pool) < count:
        pool = (pool * (count // max(1, len(pool)) + 1))[:count]
    return pool[:count]


@app.route("/nmt/simulation", methods=["GET", "POST"])
def nmt_simulation():
    """Full-length practice set for the three compulsory tests and one chosen test."""
    if active_grade() != 11:
        abort(404)
    electives = [s for s in GRADES[11] if s["slug"] in NMT_ELECTIVE_COUNTS]
    elective_map = {s["slug"]: s for s in electives}
    requested_elective = (request.form.get("elective") if request.method == "POST"
                          else request.args.get("elective", "ukr-lit"))
    if requested_elective not in elective_map:
        requested_elective = "ukr-lit" if "ukr-lit" in elective_map else electives[0]["slug"]
    started = request.method == "POST" or request.args.get("start") == "1"
    seed = request.form.get("seed", "") if request.method == "POST" else request.args.get("seed", "")
    if not seed or not seed.isalnum() or len(seed) > 40:
        seed = secrets.token_hex(8)
    rng = random.Random(seed)

    # Keep 11 algebra and 11 geometry questions in the 22-item math block.
    questions = []
    questions += nmt_question_bank(["ukr-mova"], 30, rng)
    questions += nmt_question_bank(["algebra"], 11, rng, {"algebra": "Математика"})
    questions += nmt_question_bank(["geometry"], 11, rng, {"geometry": "Математика"})
    questions += nmt_question_bank(["history-ukraine"], 30, rng)
    elective = elective_map[requested_elective]
    questions += nmt_question_bank([requested_elective], NMT_ELECTIVE_COUNTS[requested_elective], rng)
    stage1_end, stage2_end = 52, 82 + NMT_ELECTIVE_COUNTS[requested_elective]

    results = []
    if request.method == "POST":
        for index, q in enumerate(questions):
            selected = request.form.get(f"answer_{index}", "")
            correct = selected.isdigit() and int(selected) == q["answer"]
            results.append({**q, "selected": selected, "correct": correct})
    grouped = {}
    for result in results:
        row = grouped.setdefault(result["subject"], {"score": 0, "total": 0, "misses": []})
        row["total"] += 1
        row["score"] += int(result["correct"])
        if not result["correct"]:
            row["misses"].append(result)

    return show_page(
        "Повний тренувальний НМТ",
        """
        <section class="nmt-diagnostic nmt-exam-page"><nav class="crumb"><a href="{{ url_for('index', grade=11) }}">11 клас</a>　/　Повний тренувальний НМТ</nav>
          <p class="eyebrow">ВЕЛИКЕ ТРЕНУВАННЯ</p><h1>Повний тренувальний НМТ</h1>
          <p class="intro">Три обов’язкові предмети та предмет на вибір. У кожному етапі є власний таймер на 120 хвилин. Наш тренажер використовує запитання з навчальних тем, усі — з вибором однієї відповіді; це не офіційний демонстраційний варіант і не перерахунок у шкалу 100–200.</p>
          {% if not started %}<div class="nmt-results"><h2>Обери предмет на вибір</h2><p>У тренажері зібрано 30 завдань з української мови, 22 з математики, 30 з історії України та повний за кількістю запитань блок з обраного предмета.</p><form method="get"><input type="hidden" name="grade" value="11"><label class="visual-select">Предмет на вибір<select name="elective">{% for subject in electives %}<option value="{{ subject.slug }}" {{ 'selected' if subject.slug == selected_elective }}>{{ subject.name }} · {{ elective_counts[subject.slug] }} завдань</option>{% endfor %}</select></label><button class="button" name="start" value="1" type="submit">Почати тренування →</button></form><p class="muted">Етап 1: українська мова й математика · 120 хв. Етап 2: історія України й обраний предмет · 120 хв.</p></div>{% endif %}
          {% if results %}<section class="nmt-results" aria-live="polite"><h2>Результати тренування</h2><div class="career-results-grid">{% for name, score in grouped.items() %}<article><strong>{{ score.score }}/{{ score.total }}</strong><span>{{ name }}</span></article>{% endfor %}</div><p>Відповіді перевірено на цьому запиті; тренажер не зберігає їх у профілі.</p><details><summary>Переглянути теми для повторення ({{ results|selectattr('correct','equalto',false)|list|length }})</summary><ul>{% for result in results if not result.correct %}<li><strong>{{ result.subject }} · {{ result.title }}:</strong> {{ result.question }} · <a href="{{ url_for('lesson_page', subject_slug=result.slug, lesson_id=result.lesson_id, grade=11) }}">повторити тему</a></li>{% endfor %}</ul></details><p><a target="_blank" rel="noopener noreferrer" href="https://testportal.gov.ua/demonstratsijnyj-variant-nmt-2026/">Офіційні демонстраційні варіанти УЦОЯО ↗</a></p></section>{% endif %}
          {% if started %}<form method="post" class="nmt-exam-form" data-nmt-simulation data-attempt="{{ seed }}" data-results="{{ 'true' if results else 'false' }}" data-duration="7200" data-stage1-end="{{ stage1_end }}" data-stage2-end="{{ stage2_end }}">
            <input type="hidden" name="grade" value="11"><input type="hidden" name="seed" value="{{ seed }}"><input type="hidden" name="elective" value="{{ selected_elective }}">
            <div class="nmt-exam-top"><div><span class="pill">{{ questions|length }} завдань</span><span class="pill">{{ elective.name }} — предмет на вибір</span></div><div class="nmt-timer" aria-live="off"><span data-exam-stage-label>Етап 1</span><strong data-exam-timer>120:00</strong></div></div>
            {% for q in questions %}{% set question_index = loop.index0 %}<fieldset class="lesson-panel nmt-exam-question" data-question-index="{{ question_index }}" data-stage-number="{{ 1 if question_index < stage1_end else 2 }}">
              <legend><span class="pill">{{ q.subject }}</span> · {{ loop.index }}. {{ q.question }}</legend><p class="muted">Тема: {{ q.title }}</p>
              {% for option in q.options %}<label class="nmt-answer"><input type="radio" name="answer_{{ question_index }}" value="{{ loop.index0 }}" {{ 'checked' if results and results[question_index].selected == loop.index0|string }}> {{ option }}</label>{% endfor %}
              {% if results %}<p class="nmt-answer-feedback {{ 'is-correct' if results[question_index].correct else 'is-wrong' }}">{{ 'Правильно' if results[question_index].correct else 'Правильна відповідь: ' ~ q.options[q.answer] }}</p>{% endif %}</fieldset>{% endfor %}
            <div class="nmt-stage-actions"><button class="button" type="button" data-exam-next>Завершити етап 1 і перейти до етапу 2 →</button><button class="button" type="submit" data-exam-submit hidden>Завершити тренування</button><a class="access-button" href="{{ url_for('nmt_simulation', grade=11) }}">Почати спочатку</a></div>
          </form>{% endif %}
        </section>
        """,
        grade=11, started=started, questions=questions, results=results, grouped=grouped,
        elective=elective, electives=electives, selected_elective=requested_elective,
        elective_counts=NMT_ELECTIVE_COUNTS, stage1_end=stage1_end, stage2_end=stage2_end,
        seed=seed, robots_noindex=True,
    )


@app.route("/daily-practice", methods=["GET", "POST"])
def daily_practice():
    grade = active_grade()
    day = date.today().isoformat()
    courses = GRADES[grade]
    ordinal = date.today().toordinal()
    subject = courses[ordinal % len(courses)]
    lesson_id = (ordinal // len(courses)) % len(subject["lessons"]) + 1
    lesson = subject["lessons"][lesson_id - 1]
    questions = lesson.get("control_work") or [{
        "question": lesson.get("question", "Яке твердження відповідає темі?"),
        "options": lesson.get("options", ["Застосувати правило теми", "Ігнорувати умову", "Відповісти навмання"]),
        "answer": lesson.get("answer", 0),
    }]
    question = questions[ordinal % len(questions)]
    selected = request.form.get("answer", "") if request.method == "POST" else ""
    answered = request.method == "POST"
    correct = selected.isdigit() and int(selected) == question["answer"]
    return show_page(
        "Щоденна практика",
        """
        <section class="daily-page"><nav class="crumb"><a href="{{ url_for('index', grade=grade) }}">{{ grade }} клас</a>　/　Завдання дня</nav>
          <p class="eyebrow">ОДНЕ КОРОТКЕ ЗАВДАННЯ ЩОДНЯ</p><h1>Практика на сьогодні</h1>
          <p class="intro">{{ subject.icon }} {{ subject.name }} · {{ lesson.title }}. Спробуй відповісти самостійно, а потім переглянь пояснення.</p>
          {% if answered %}<section class="nmt-results daily-result" aria-live="polite"><h2>{{ 'Вірно! Гарна робота 🌟' if correct else 'Розберімо відповідь' }}</h2><p>{{ lesson.explain }}</p><p><strong>Правильна відповідь:</strong> {{ question.options[question.answer] }}</p><a class="button" href="{{ url_for('lesson_page', subject_slug=subject.slug, lesson_id=lesson_id, grade=grade) }}">Перейти до теми →</a><span hidden data-daily-complete data-daily-key="{{ day }}"></span></section>{% endif %}
          <form method="post" class="nmt-diagnostic-form daily-question"><fieldset class="lesson-panel"><legend>{{ question.question }}</legend>{% for option in question.options %}<label class="nmt-answer"><input type="radio" name="answer" value="{{ loop.index0 }}" {{ 'checked' if selected == loop.index0|string }} required> {{ option }}</label>{% endfor %}</fieldset><button class="button" type="submit">Перевірити</button></form>
        </section>
        """,
        grade=grade, subject=subject, lesson=lesson, lesson_id=lesson_id, question=question,
        day=day, answered=answered, correct=correct, selected=selected, robots_noindex=True,
    )


